PROGRAM ST190_SORTERING
VAR
    steg      : INT := 0;
    trigPart  : R_TRIG;
    tmrPush   : TON;
    tmrHem    : TON;
    xPushOn   : BOOL := FALSE;
    xVantarHem: BOOL := FALSE;
    xUteFel   : BOOL := FALSE;
    xTrangsel : BOOL := FALSE;
    xDrift    : BOOL := FALSE;
    p1Giltig  : BOOL := FALSE;
    p1Hog     : BOOL := FALSE;
    p1Pos     : REAL := 0.0;
    p2Giltig  : BOOL := FALSE;
    p2Hog     : BOOL := FALSE;
    p2Pos     : REAL := 0.0;
    rUtlos    : REAL := 260.0;
END_VAR

(* Skiftregistret har TVA platser, och det ar en rakning och ingen smaksak.
   Takten ar 60 burkar per minut, alltsa 1,0 s per burk, och vid 0,35 m/s
   ligger burkarna 350 mm isar. Mellan hojdgivaren och utskjutaren ar det
   400 mm, alltsa 400/350 = 1,14 burkar: tva burkar kan vara pa vag mellan
   givaren och utskjutaren samtidigt. En enda plats hade tappat den ena, och
   nasta burk hade arvt foregaende burks besked. *)

(* EMG_OK ar sakerhetskretsens egen OK-kontakt. Den gar hog forst nar kretsen
   ar manuellt aterstalld i sakerhetsdelen, sa den har logiken aterstaller
   aldrig sjalv ett nodstopp: den ar forreglad AV kretsen och laser den bara. *)

trigPart(CLK := ST190_PEC_PART);
tmrPush(IN := xPushOn, PT := T#400ms);
xVantarHem := (steg = 3) AND NOT ST190_PSH_HOME;
tmrHem(IN := xVantarHem, PT := T#1s);

(* En utskjutare som inte kommer hem far inte matas med fler burkar. Retur-
   slaget ar samma storlek som utslaget, 0,4 s, sa 1,0 s ar mer an dubbla
   returtiden och slar inte pa ett normalt slag. *)
IF tmrHem.Q THEN
    xUteFel := TRUE;
END_IF;
IF ST190_PSH_HOME THEN
    xUteFel := FALSE;
END_IF;

xDrift := EMG_OK AND AIR_OK AND NOT xUteFel AND NOT xTrangsel;

(* Bedomningen sker EN gang, pa hojdgivarens stigande flank, och lagras
   tillsammans med bandets strackning i samma ogonblick. Sedan ar givaren
   ointressant for just den burken. *)
IF trigPart.Q THEN
    IF NOT p1Giltig THEN
        p1Pos := ST190_ENC_POS;
        p1Hog := ST190_HGT_HIGH;
        p1Giltig := TRUE;
    ELSIF NOT p2Giltig THEN
        p2Pos := ST190_ENC_POS;
        p2Hog := ST190_HGT_HIGH;
        p2Giltig := TRUE;
    ELSE
        xTrangsel := TRUE;
    END_IF;
END_IF;

IF NOT xDrift THEN
    (* Registret behalls. Burkarna star kvar pa banan och deras beskeder med
       dem; ett register som nollstalls vid stopp sorterar fel pa varenda
       burk som redan ar bedomd. *)
    xPushOn := FALSE;
    IF steg = 2 THEN
        steg := 3;
    END_IF;
ELSE
    CASE steg OF
        0:
            (* 400 mm till utskjutaren vid 0,35 m/s ar 1,143 s. Slagtiden ar
               0,4 s, sa kommandot ska ges 1,143 - 0,4 = 0,743 s efter
               flanken, alltsa efter 0,743 * 350 = 260 mm bandstrackning.
               Registret bars framat av ST190_ENC_POS och aldrig av klockan:
               saktar bandet in flyttar sig burken langsammare, men den
               strackning som skiljer givaren fran utskjutaren ar densamma. *)
            IF p1Giltig AND ((ST190_ENC_POS - p1Pos) >= rUtlos) THEN
                IF p1Hog THEN
                    steg := 4;
                ELSE
                    xPushOn := TRUE;
                    steg := 2;
                END_IF;
            END_IF;
        2:
            IF tmrPush.Q THEN
                xPushOn := FALSE;
                steg := 3;
            END_IF;
        3:
            IF ST190_PSH_HOME THEN
                steg := 4;
            END_IF;
        4:
            p1Giltig := p2Giltig;
            p1Hog := p2Hog;
            p1Pos := p2Pos;
            p2Giltig := FALSE;
            xTrangsel := FALSE;
            steg := 0;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

ST190_CNV_RUN := xDrift;
ST190_PSH_OUT := xPushOn;
END_PROGRAM

